    'COM_PRIVACY' => 'Privacidad',
    'COM_PRIVACY_ADMIN_NOTIFICATION_USER_CONFIRMED_REQUEST_MESSAGE' => 'El usuario %1$s ha confirmado su solicitud de información.',
    'COM_PRIVACY_ADMIN_NOTIFICATION_USER_CONFIRMED_REQUEST_SUBJECT' => 'Solicitud de información confirmada por el usuario',
    'COM_PRIVACY_ADMIN_NOTIFICATION_USER_CREATED_REQUEST_MESSAGE' => 'Se ha enviado una nueva solicitud de información por %1$s.',
    'COM_PRIVACY_ADMIN_NOTIFICATION_USER_CREATED_REQUEST_SUBJECT' => 'Solicitud de información enviada.',
    'COM_PRIVACY_CONFIRM_REMIND_SUCCEEDED' => 'Su consentimiento a las Políticas de Privacidad de este sitio web ha sido extendido.',
    'COM_PRIVACY_CONFIRM_REQUEST_FIELDSET_LABEL' => "Se ha enviado un mensaje a su dirección de correo electrónico. Por favor, pegue el 'token' de confirmación del correo electrónico en el siguiente campo para demostrar que usted es el propietario de la información solicitada.",
    'COM_PRIVACY_CONFIRM_REQUEST_SUCCEEDED' => 'Su solicitud de información ha sido confirmada. Procesaremos su solicitud lo antes posible y el resultado se enviará a su correo electrónico.',
    'COM_PRIVACY_CREATE_REQUEST_SUCCEEDED' => 'Su solicitud de información ha sido creada. Antes de que se pueda procesar, debe verificar esta solicitud. Se ha enviado un correo electrónico a su dirección con instrucciones adicionales para completar esta verificación.',
    'COM_PRIVACY_EMAIL_REQUEST_BODY_EXPORT_REQUEST' => "Alguien ha creado una solicitud para exportar toda la información personal relacionada con esta dirección de correo electrónico en {URL}. Como medida de seguridad, debe confirmar que se trata de una solicitud válida para eliminar su información personal de este sitio web. Si se trata de un error ignore este correo y no sucederá nada\n\nA fin de confirmar esta solicitud, puede completar una de las siguientes tareas:\n\n1. Visite la siguiente URL: {TOKENURL} \n\n2. Copie su token de este correo electrónico, visite la URL referenciada y pegue su token en el formulario.\nURL: {FORMURL}\nToken: {TOKEN}\n\nTenga en cuenta que este token solo es válido durante 24 horas desde el momento en que el correo electrónico fue enviado.",
    'COM_PRIVACY_EMAIL_REQUEST_BODY_REMOVE_REQUEST' => "Alguien ha creado una solicitud para eliminar toda la información personal relacionada con esta dirección de correo electrónico en {URL}. Como medida de seguridad, debe confirmar que se trata de una solicitud válida para eliminar su información personal de este sitio web. Si se trata de un error ignore este correo y no sucederá nada\n\nA fin de confirmar esta solicitud, puede completar una de las siguientes tareas:\n\n1. Visite la siguiente URL: {TOKENURL} \n\n2. Copie su token de este correo electrónico, visite la URL referenciada y pegue su token en el formulario.\nURL: {FORMURL}\nToken: {TOKEN}\n\nTenga en cuenta que este token solo es válido durante 24 horas desde el momento en que el correo electrónico fue enviado.",
    'COM_PRIVACY_EMAIL_REQUEST_SUBJECT_EXPORT_REQUEST' => 'Solicitud de información creada en {SITENAME}',
    'COM_PRIVACY_EMAIL_REQUEST_SUBJECT_REMOVE_REQUEST' => 'Solicitud de eliminación de información creada en {SITENAME}',
    'COM_PRIVACY_ERROR_CANNOT_CREATE_REQUEST_WHEN_SENDMAIL_DISABLED' => 'No se puede crear una solicitud de información cuando el soporte de correo electrónico está deshabilitado.',
    'COM_PRIVACY_ERROR_CHECKING_FOR_EXISTING_REQUESTS' => 'Se produjo un error al verificar las solicitudes de información existentes, intente enviar esta solicitud nuevamente.',
    'COM_PRIVACY_ERROR_CONFIRM_TOKEN_EXPIRED' => 'El token de confirmación para su solicitud de información ha caducado. Deberá enviar una nueva solicitud.',
