    'COM_USERS_ACTIVATION_TOKEN_NOT_FOUND' => 'Código de verificación no encontrado. Verifique si su cuenta ya está activada e intente acceder.',
    'COM_USERS_CAPTCHA_LABEL' => 'Captcha',
    'COM_USERS_DATABASE_ERROR' => 'Error obteniendo al usuario desde la base de datos: %s',
    'COM_USERS_EDIT_PROFILE' => 'Editar perfil',
    'COM_USERS_EMAIL_ACCOUNT_DETAILS' => 'Detalles de la cuenta para {NAME} de {SITENAME}',
    'COM_USERS_EMAIL_ACTIVATED_BY_ADMIN_ACTIVATION_BODY' => "Hola, {NAME}:\n\nSu cuenta ha sido activada por un administrador. Ahora ya puede acceder e identificarse en {SITEURL} usando el usuario {USERNAME} y la contraseña que eligió durante el proceso de registro.",
    'COM_USERS_EMAIL_ACTIVATED_BY_ADMIN_ACTIVATION_SUBJECT' => 'Cuenta activada para {NAME} de {SITENAME}',
    'COM_USERS_EMAIL_ACTIVATE_WITH_ADMIN_ACTIVATION_BODY' => "Hola, administrador:\n\nUn nuevo usuario se ha registrado en {SITENAME}.\nEl usuario ha verificado su correo electrónico y espera a que usted apruebe su solicitud de cuenta.\nEste correo contiene sus detalles:\n\nNombre: {NAME}\nCorreo: {EMAIL}\nUsuario: {USERNAME}\n\nPuede activar al usuario seleccionando el enlace de abajo:\n{ACTIVATE}\n",
    'COM_USERS_EMAIL_ACTIVATE_WITH_ADMIN_ACTIVATION_SUBJECT' => 'Se necesita de la aprobación de registro para la cuenta de {NAME} en {SITENAME}',
    'COM_USERS_EMAIL_PASSWORD_RESET_BODY' => "Hola,\n\nSe ha realizado una solicitud para restablecer su contraseña en {SITENAME}. Para restablecerla, debe introducir este código de verificación para confirmar que la solicitud es legítima.\n\nEl código de verificación es {TOKEN}\n\nSeleccione la URL de abajo para continuar con el restablecimiento:\n\n{LINK_TEXT}\n\nGracias.",
    'COM_USERS_EMAIL_PASSWORD_RESET_SUBJECT' => 'Solicitud de restablecimiento de contraseña en {SITENAME}',
    'COM_USERS_EMAIL_REGISTERED_BODY' => "Hola, {NAME},\n\nGracias por registrarse en {SITENAME}.\n\nAhora ya puede acceder a {SITEURL} usando el siguiente nombre de usuario y contraseña:\n\nUsuario: {USERNAME}\nContraseña: {PASSWORD_CLEAR}",
    'COM_USERS_EMAIL_REGISTERED_BODY_NOPW' => "Hola, {NAME},\n\nGracias por registrarse en {SITENAME}.\n\nAhora ya puede acceder a {SITEURL} usando el nombre de usuario y contraseña con los que se registró.",
    'COM_USERS_EMAIL_REGISTERED_NOTIFICATION_TO_ADMIN_BODY' => "Hola, administrador,\n\nSe ha registrado un nuevo usuario '{NAME}', con nombre de usuario '{USERNAME}', en {SITEURL}.",
    'COM_USERS_EMAIL_REGISTERED_WITH_ACTIVATION_BODY' => "Hola, {NAME}:\n\nGracias por registrarse en {SITENAME}. Su cuenta ha sido creada y debe ser activada antes de que la pueda usar.\nPara activar la cuenta, haga clic en el siguiente enlace o copie y pegue la URL completa en su navegador:\n{ACTIVATE}\n\nTras la activación, ya podrá acceder a {SITEURL} usando los siguientes datos:\n\nUsuario: {USERNAME}\nContraseña: {PASSWORD_CLEAR}",
    'COM_USERS_EMAIL_REGISTERED_WITH_ACTIVATION_BODY_NOPW' => "Hola, {NAME},\n\nGracias por registrarse en {SITENAME}. Su cuenta se ha creado y deberá ser activada antes de que pueda usarla.\nPara activar la cuenta, haga clic en el siguiente enlace o cópielo en su navegador:\n{ACTIVATE}\n\nDespués de la activación puede identificarse en {SITEURL} usando el siguiente nombre de usuario junto a la contraseña que introdujo durante el proceso de registro:\n\nUsuario: {USERNAME}",
    'COM_USERS_EMAIL_REGISTERED_WITH_ADMIN_ACTIVATION_BODY' => "Hola, {NAME}:\n\nGracias por registrarse en {SITENAME}. Su cuenta ha sido creada y necesita ser verificada antes de que pueda usarla.\nPara activar la cuenta, seleccione el siguiente enlace o copie y pegue la URL completa en su navegador:\n{ACTIVATE}\n\nDespués de la verificación un administrador será notificado para que active la cuenta. Recibirá una confirmación cuando se haya hecho.\nUna vez activada, podrá acceder a {SITEURL} usando el siguiente usuario y contraseña:\n\nUsuario: {USERNAME}\nContraseña: {PASSWORD_CLEAR}",
    'COM_USERS_EMAIL_REGISTERED_WITH_ADMIN_ACTIVATION_BODY_NOPW' => "Hola, {NAME},\n\nGracias por registrarse en {SITENAME}. Su cuenta ha sido creada y deberá ser verificada antes de que pueda usarla.\n\nPara verificar la cuenta, haga clic en el siguiente enlace o cópielo en su navegador:\n{ACTIVATE}\n\nDespués de verificar la cuenta, un administrador recibirá una notificación para su activación. Cuando el administrador la haya activado, recibirá una confirmación.\n\nDespués de esto, podrá identificarse en {SITEURL} usando el siguiente nombre de usuario junto a la contraseña que introdujo durante el proceso de registro:\n\nUsuario: {USERNAME}",
    'COM_USERS_EMAIL_USERNAME_REMINDER_BODY' => "Hola,\n\nSe ha recibido una solicitud para recordar su usuario en {SITENAME}.\n\nSu usuario es {USERNAME}.\n\nPara acceder a su cuenta, seleccione el enlace de abajo.\n\n{LINK_TEXT}\n\nGracias.",
