    'COM_PRIVACY_CONFIRM_REQUEST_FIELDSET_LABEL' => 'Se ha enviado un mensaje a su dirección de correo electrónico. Por favor, confirme nuevamente su dirección de correo electrónico y pegue el token de confirmación del correo electrónico al siguiente campo para demostrar que es el propietario de la información solicitada.',
    'COM_PRIVACY_CONFIRM_REQUEST_SUCCEEDED' => 'Su solicitud de información ha sido confirmada. Procesaremos su solicitud lo antes posible y la respuesta se enviará a su correo electrónico.',
    'COM_PRIVACY_CREATE_REQUEST_SUCCEEDED' => 'Su solicitud de información ha sido creada. Antes de que se pueda procesar, debe verificar esta solicitud. Se ha enviado un correo electrónico a su dirección con instrucciones adicionales para completar esta verificación.',
    'COM_PRIVACY_EMAIL_REQUEST_BODY_EXPORT_REQUEST' => "Alguien ha creado una solicitud para exportar toda la información personal relacionada con esta dirección de correo electrónico en [URL]. Como medida de seguridad, debe confirmar que se trata de una solicitud válida para su información personal desde este sitio web. Si se trata de un error, simplemente ignore este correo electrónico y no sucederá nada.\n\nPara confirmar esta solicitud, puede completar una de las siguientes tareas:\n\n1. Visite la siguiente URL: [TOKENURL]\n\n2. Copie su token de este correo electrónico, visite la URL referenciada y pegue su token en el formulario.\nURL: [FORMURL]\nToken: [TOKEN]\n\nTenga en cuenta que este token solo es válido durante 24 horas desde el momento en que el correo electrónico fue enviado.",
    'COM_PRIVACY_EMAIL_REQUEST_BODY_REMOVE_REQUEST' => "Alguien ha creado una solicitud para eliminar toda la información personal relacionada con esta dirección de correo electrónico en [URL]. Como medida de seguridad, debe confirmar que se trata de una solicitud válida para eliminar su información personal de este sitio web. Si se trata de un error, simplemente ignore este correo electrónico y no sucederá nada.\n\nA fin de confirmar esta solicitud, puede completar una de las siguientes tareas:\n\n1. Visite la siguiente URL: [TOKENURL] \n\n2. Copie su token de este correo electrónico, visite la URL referenciada y pegue su token en el formulario.\nURL: [FORMURL]\nToken: [TOKEN]\n\nTenga en cuenta que este token solo es válido durante 24 horas desde el momento en que el correo electrónico fue enviado.",
    'COM_PRIVACY_EMAIL_REQUEST_SUBJECT_EXPORT_REQUEST' => 'Solicitud de información creada en [SITENAME]',
