    'COM_USERS_EMAIL_ACCOUNT_DETAILS' => 'Detalles de la cuenta para %s de %s',
    'COM_USERS_EMAIL_ACTIVATE_WITH_ADMIN_ACTIVATION_BODY' => "Hola, administrador:\n\nUn nuevo usuario se ha registrado en %s.\nEl usuario ha verificado su correo electrónico y espera a que usted apruebe su solicitud de cuenta.\nEste correo contiene sus detalles:\n\n Nombre: %s \n Correo: %s \n Usuario: %s \n\nPuede activar al usuario seleccionando el enlace de abajo:\n %s \n",
    'COM_USERS_EMAIL_ACTIVATE_WITH_ADMIN_ACTIVATION_SUBJECT' => 'Se necesita de la aprobación de registro para la cuenta de %s en %s',
    'COM_USERS_EMAIL_ACTIVATED_BY_ADMIN_ACTIVATION_BODY' => "Hola, %s:\n\nSu cuenta ha sido activada por un administrador. Ahora ya puede acceder e identificarse en %s usando el usuario %s y contraseña que eligió durante el proceso de registro.",
    'COM_USERS_EMAIL_ACTIVATED_BY_ADMIN_ACTIVATION_SUBJECT' => 'Cuenta activada para %s de %s',
    'COM_USERS_EMAIL_PASSWORD_RESET_BODY' => "Hola,\n\nSe ha realizado una solicitud para restablecer su %s contraseña de la cuenta. Para restablecer la contraseña, necesita enviar este código de verificación, para que se pueda verificar que la solicitud es legítima.\n\nEl código de verificación es %s\n\nSeleccione la URL de abajo para poder proceder a restablecer su contraseña.\n\n %s \n\nGracias.",
    'COM_USERS_EMAIL_PASSWORD_RESET_SUBJECT' => 'Su %s solicitud de restablecimiento de contraseña',
    'COM_USERS_EMAIL_REGISTERED_BODY' => "Hola %s,\n\nGracias por registrarse en %s.\n\nAhora ya puede acceder a %s usando el siguiente nombre de usuario y contraseña:\n\nUsuario: %s\nContraseña: %s",
    'COM_USERS_EMAIL_REGISTERED_BODY_NOPW' => "Hola %s,\n\nGracias por registrarse en %s.\n\nAhora ya puede acceder a %s usando el nombre de usuario y contraseña con los que se registró.",
    'COM_USERS_EMAIL_REGISTERED_NOTIFICATION_TO_ADMIN_BODY' => "Hola, administrador, \n\nSe ha registrado un nuevo usuario '%s', con nombre de usuario '%s', en %s.",
    'COM_USERS_EMAIL_REGISTERED_WITH_ACTIVATION_BODY' => "Hola, %s:\n\nGracias por registrarse en %s. Su cuenta ha sido creada y debe ser activada antes de que la pueda usar.\nPara activar la cuenta, seleccione el siguiente enlace o copie y pegue la URL completa en su navegador:\n%s \n\nTras la activación, ya podrá acceder a %s usando el siguiente usuario y contraseña:\n\nUsuario: %s\nContraseña: %s",
    'COM_USERS_EMAIL_REGISTERED_WITH_ACTIVATION_BODY_NOPW' => "Hola %s,\n\nGracias por registrarse en %s. Su cuenta se ha creado y deberá ser activada antes de que pueda usarla.\nPara activar la cuenta, seleccione el siguiente enlace o cópielo en su navegador:\n%s \n\nDespués de la activación puede identificarse en %s usando el siguiente nombre de usuario junto a la contraseña que introdujo durante el proceso de instalación:\n\nUsuario: %s",
    'COM_USERS_EMAIL_REGISTERED_WITH_ADMIN_ACTIVATION_BODY' => "Hola, %s:\n\nGracias por registrarte en %s. Su cuenta ha sido creada y necesita ser verificada antes de que pueda usarla.\nPara activar la cuenta, seleccione el siguiente enlace o copie y pegue la URL completa en su navegador:\n %s \n\nDespués de la verificación un administrador será advertido para que active la cuenta. Recibirá una confirmación cuando se haya hecho.\nUna vez que la cuenta se haya activado, podrá acceder a %s usando el siguiente usuario y contraseña:\n\nUsuario: %s\nContraseña: %s",
    'COM_USERS_EMAIL_REGISTERED_WITH_ADMIN_ACTIVATION_BODY_NOPW' => "Hola %s,\n\nGracias por registrarse en %s. Su cuenta ha sido creada y deberá ser verificada antes de que pueda usarla.\nPara verificar la cuenta, seleccione el siguiente enlace o cópielo en su navegador:\n %s \n\nDespués de que usted haya verificado la cuenta, un administrador recibirá una notificación para la activación de la cuenta. Cuando el administrador la haya activado, usted recibirá una confirmación.\nDespués de esto, usted podrá identificarse en %s usando el siguiente nombre de usuario junto a la contraseña que introdujo durante el proceso de registro:\n\nUsuario: %s",
    'COM_USERS_EMAIL_USERNAME_REMINDER_BODY' => "Hola,\n\nSe ha recibido una solicitud para recordar su usuario desde su cuenta en %s .\n\nSu usuario es %s.\n\nPara acceder a su cuenta, seleccione el enlace de abajo.\n\n%s \n\nGracias.",
    'COM_USERS_EMAIL_USERNAME_REMINDER_SUBJECT' => 'Su %s usuario',
    'COM_USERS_ERROR_SECRET_CODE_WITHOUT_TFA' => 'Usted ha introducido un código secreto pero la autenticación de doble factor no está habilitada desde el perfil de su cuenta. Si desea usar un código secreto para asegurar su acceso, por favor, edite su perfil de usuario y habilite la autenticación de doble factor.',
    'COM_USERS_FIELD_PASSWORD_RESET_DESC' => 'Por favor, introduzca la dirección de correo electrónico que tiene asociada con su cuenta de usuario.<br />Se le enviará un código de verificación. Una vez que haya recibido su código de verificación, podrá elegir una nueva contraseña para su cuenta.',
